contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 seed) public payable {
        address target = address(uint160(uint256(keccak256(abi.encodePacked(seed)))));
        uint256 targetBefore = c.balances(target); if (__ESBMC_reverted()) return;
        uint256 reserveBefore = address(c).balance;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 targetAfter = c.balances(target); if (__ESBMC_reverted()) return;
        uint256 reserveAfter = address(c).balance;

        assert(
            reverted
                ? (targetBefore > reserveBefore && targetAfter == targetBefore && reserveAfter == reserveBefore)
                : (targetBefore <= reserveBefore && targetAfter == 0 && reserveAfter + targetBefore == reserveBefore)
        );
    }

    receive() external payable {}
}

