pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(uint256 seed) internal {
        address target = address(uint160(uint256(keccak256(abi.encodePacked(seed)))));
        uint256 targetBefore;
        try c.balances(target) returns (uint256 __r) { targetBefore = __r; } catch { return; }
        uint256 reserveBefore = address(c).balance;
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 targetAfter;
        try c.balances(target) returns (uint256 __r) { targetAfter = __r; } catch { return; }
        uint256 reserveAfter = address(c).balance;
        assertTrue(reverted
                ? (targetBefore > reserveBefore && targetAfter == targetBefore && reserveAfter == reserveBefore)
                : (targetBefore <= reserveBefore && targetAfter == 0 && reserveAfter + targetBefore == reserveBefore));
    }

    function testFuzz_run(uint256 seed) public {
        _run(seed);
    }

    receive() external payable {}
}
